redirect:
to => {
      // 外部版:跳转到“日志提取任务”
      if (window.IS_EXTERNAL && JSON.parse(window.IS_EXTERNAL)) {
        return {
          path: '/manage/log-extract-task',
          query: {
            spaceUid: to.query.spaceUid,
            bizId: to.query.bizId,
          },
        };
      }
      // 内部版:跳转到“采集项列表”
      return {
        path: '/manage/log-collection/collection-item',
        query: {
          spaceUid: to.query.spaceUid,
          bizId: to.query.bizId,
        },
      };
    }

